Q: How do i show text based on the button user clicked A: <p>With no HTML given at time of writing the following is merely a possible solution.
Instead of using an array you could use a regular Object literal with keys defined to match some parameter of the buttons within the HTML - below uses the <code>value</code> of the button. A simple lookup using the value returns the corresponding sub-object which can then be accessed using dot notation.</p>
<p><div class="snippet" data-lang="js" data-hide="false" data-console="true" data-babel="false" data-babel-preset-react="false" data-babel-preset-ts="false">
<div class="snippet-code">
<pre class="snippet-code-js lang-js prettyprint-override"><code>// utility for querySelector
const q=(e,n=document)=&gt;n.querySelector(e);

// lookup object literal
const sections={
  'About':{title:'Our History',description:'As a company we thr...'},
  'Goals':{title:'Our Goals',description:'Our goals are as follows...'},
  'Team':{title:'Our Team',description:'Our Team consists of...'},
  'Values':{title:'Our Values',description:'The values we protect here at 45 Degrees are...'},
  'Why':{title:'Why',description:'The Why is one of our favorite things to talk about...'},
};

// delegated click event handler bound to button parent container
document.querySelector('div[id="btns"]').addEventListener('click',e=&gt;{
  q('main.maininfo h2').textContent=sections[e.target.value].title;
  q('main.maininfo p').textContent=sections[e.target.value].description;
});</code></pre>
<pre class="snippet-code-css lang-css prettyprint-override"><code>#btns{display:flex;width:100%;margin:1rem auto;}
[type='button']{flex:1;margin:0.25rem;padding:0.25rem}</code></pre>
<pre class="snippet-code-html lang-html prettyprint-override"><code>&lt;div id='btns' class='choices'&gt;
  &lt;input type='button' name='btn1' value='About' /&gt;
  &lt;input type='button' name='btn2' value='Goals' /&gt;
  &lt;input type='button' name='btn3' value='Team' /&gt;
  &lt;input type='button' name='btn4' value='Values' /&gt;
  &lt;input type='button' name='btn5' value='Why' /&gt;
&lt;/div&gt;

&lt;main class='maininfo'&gt;
  &lt;h2&gt;&lt;/h2&gt;
  &lt;p&gt;&lt;/p&gt;
&lt;/main&gt;</code></pre>
</div>
</div>
</p>

